@lru_cache(4096)
def _ml(t:str)->tuple:
    g=[];t=re.sub(r"[。！？；؟]",' . ',t.replace('đ','d')).replace('，',',').replace('、',',').replace('،',',')
    for x,r,p in MLR:t,n=re.subn(r,p,t);g+=[x]*bool(n)
    t=''.join(c for c in unicodedata.normalize('NFKD',t) if not unicodedata.combining(c))
    for x,r,p in MLL:t,n=r.subn(p or (lambda m:' my '+KINX[next(v for v in m.groups() if v)]+' '),t);g+=[x]*bool(n)
    return t,(g[0] if g else 'zh' if re.search(r"[\u4e00-\u9fff]",t) else 'ar' if re.search(r"[\u0600-\u06ff]",t) else None)
def _low(s:str)->str:return re.sub(r"[’‘`´]","'",re.sub(r"[\U0001F602\U0001F923\U0001F480]",' lol ',(s or '').lower())).replace("'",'')
def lang(text:str)->Optional[str]:return _ml(_low(text))[1]
def norm(s:str)->str:
    t=_ml(_low(s))[0]
    t=re.sub(r"[.!?;:\n]+",' . ',t);t=t.replace(',',' , ').replace('&',' and ');t=re.sub(r"[^a-z0-9 .,]",' ',t)
    t=' '.join(_fix(w) for w in t.split())
    for a,b in MW:t=re.sub(a,b,t)
    return ' '+re.sub(r"\s+",' ',t).strip()+' '
