SUBX=re.compile(rf"\b(?:(?P<self>i|im|me|my|myself|ive|ill)|(?P<kid>{KID})|(?P<kin>{KIN})|(?P<oth>he|she|hes|shes|him|her|they|someone|somebody|guy|man|woman|girl|boy|person|lady))\b");TOKR=re.compile(r"[a-z0-9']+")
def efeats(text:str)->list:
    t=norm(text);w=TOKR.findall(t);g=globals();return ['w'+x for x in w]+['b'+a+'_'+b for a,b in zip(w,w[1:])]+['m'+k for k in MKN if g[k].search(t)]+['j'+m.lastgroup for m in SUBX.finditer(t)]+['len%d'%min(len(w)//5,8)]+['i'+n for n,rx in IND if rx.search(t)]+['l'+str(lang(text))]
def _ix(fs)->np.ndarray:return np.unique(np.fromiter((zlib.crc32(f.encode())&EM for f in fs),np.int64))
def _fit(X,Y)->np.ndarray:
    C=np.bincount(np.concatenate([x+y*(EM+1) for x,y in zip(X,Y)]),minlength=8<<EB).reshape(8,-1).astype(np.float64);n=np.bincount(Y,minlength=8).astype(np.float64);P=C[1:].sum(0);q=lambda a,b:np.log((a+EA)/(b+2*EA))
    return np.clip(np.stack([q(P,n[1:].sum())-q(C[0],n[0])]+[q(C[c],n[c])-q(P-C[c],n[1:].sum()-n[c]) for c in range(1,8)],1),-ECL,ECL)
def _enc(W)->np.ndarray:
    v=np.rint(W*EQ).astype(np.int64)+EO;return np.stack([(v//k)%17 for k in K4],-1).astype(np.uint8)
def _dec(d)->np.ndarray:return (sum(d[...,i].astype(np.int32)*k for i,k in enumerate(K4))-EO).astype(np.int16)
def _sc(W,x)->tuple:
    s=W[x].sum(0);return s[0]/EQ/np.sqrt(max(len(x),1)),EC[1+int(np.argmax(s[1:]))]
def train(out=LUTP,sets=('dev','blind1','blind2','blind3','blind4','blind5','blind6','blind7'),fp=0.01,fpc=0.005)->dict:
    D=Path(__file__).resolve().parents[2]/'tests'/'data'/'emergency';lk={**EL.verify(D/'lock.json'),**EL.verify(D/'lock_blind567.json')};assert not lk,lk
    R=[(s,c if p=='pos' else 'none',m) for s in sets for p in ('pos','neg') for c,m in (l.rstrip('\n').split('\t',1) for l in open(D/f'{s}_{p}.tsv',encoding='utf-8') if l.strip())]
    X=[_ix(efeats(m)) for *_,m in R];Y=np.array([EC.index(c) for _,c,_ in R]);S=np.array([s for s,*_ in R]);L=np.zeros(len(R));G=[None]*len(R)
    for s in sets:
        k=S!=s;W=_dec(_enc(_fit([x for x,j in zip(X,k) if j],Y[k])))
        for i in np.flatnonzero(~k):L[i],G[i]=_sc(W,X[i])
    y=Y>0;th=float(np.quantile(L[~y],1-fp));W=_enc(_fit(X,Y));p=L>=th;su=np.array([g=='suicide' for g in G]);ns=np.sort(L[~y&su&~p])[::-1];kc=int(fpc*(~y).sum());tc=float(ns[kc])+1e-9 if len(ns)>kc else th;pc=p|su&(L>=tc)
    m={'th':th,'th_veto':float(np.quantile(L[y],0.02)),'th_concern':tc,'loso_recall':float(p[y].mean()),'loso_fp':float(p[~y].mean()),'loso_recall_with_concern':float(pc[y].mean()),'loso_fp_with_concern':float(pc[~y].mean()),'loso_suicide_recall_with_concern':float(pc[Y==2].mean()),'loso_suicide_recall':float(p[Y==2].mean()),'loso_cat_acc':float(np.mean([G[i]==EC[Y[i]] for i in np.flatnonzero(y)])),'n':len(R),'bits':EB,'alpha':EA,'clip':ECL,'q':EQ,'offset':EO,'splits_hash':json.loads((D/'lock.json').read_text())['splits_hash'],'splits_hash_567':json.loads((D/'lock_blind567.json').read_text())['splits_hash'],'sets':list(sets)}
    out and np.savez_compressed(out,d=W,th=np.float64(th),meta=np.array(json.dumps(m)));[f.cache_clear() for f in (_lut,lut_score,detect)];return m
@lru_cache(1)
def _lut():
    z=np.load(LUTP) if LUTP.exists() else None;d=z['d'] if z is not None else None;return (np.concatenate([_dec(d[i:i+32768]) for i in range(0,len(d),32768)]),float(z['th']),float(json.loads(str(z['meta']))['th_veto']),float(json.loads(str(z['meta'])).get('th_concern',z['th']))) if z is not None else None
@lru_cache(2048)
def lut_score(text:str)->tuple:
    z=_lut();return _sc(z[0],_ix(efeats(text))) if z and (text or '').strip() else (0.0,None)
def _gd(text:str)->set:
    t=norm(text);hs,b=_hits(t);return {_guarded(t,h,b) for h in hs}|({'ex'} if any(ex and rx.search(t) and ex.search(t) for n,rx,md,ex,rq in SPECS) else set())
def classify(text:str)->Optional[dict]:
    z=_lut();v,c=lut_score(text);k=(EK[c] if v>=z[1] else 'concern' if c=='suicide' and v>=z[3] and FP1.search(norm(text)) else None) if z and c else None;k=None if k and v<z[1]+EGM and _gd(text)&GDL else k
    return {'category':c,'kind':k,'reply':T[k],'match':'','norm':norm(text).strip(),'score':round(float(v),3),'src':'lut'} if k else None
if __name__=='__main__':print(train())
